import type { Project } from '../../types'
import type { ReportDocumentDef, ReportMeta, SectionBlock } from './types'

export type ExportFormat = 'json' | 'markdown'

export const SUPPORTED_EXPORT_FORMATS: readonly ExportFormat[] = ['json', 'markdown']

const DEMO_NOTICE =
  'Demo export: this file was generated by the Raptix web console demo build from sample fixture data. ' +
  'It is not derived from a live engagement and must not be used as a real assessment deliverable.'

export const CAPABILITY_LIMITS = {
  pdf: 'PDF export needs the document generation service, which is not part of this demo build. JSON and Markdown downloads are available.',
  docx: 'DOCX export needs the document generation service, which is not part of this demo build. JSON and Markdown downloads are available.',
  sign: 'Signing and finalization need the backend attestation service, which is not part of this demo build.',
  share: 'Secure share links need the backend delivery service, which is not part of this demo build.',
  aiCompile: 'AI report compilation needs the agent runtime, which is not part of this demo build.',
  aiCopilot: 'The AI report co-pilot needs the agent runtime, which is not part of this demo build.',
  edit: 'Inline report editing is not supported in this read-only demo preview.',
  addSection: 'Custom report sections are not supported in this demo build.',
} as const

export function slugify(value: string): string {
  const slug = value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
  return slug || 'report'
}

export function buildExportFilename(projectName: string, report: ReportMeta, format: ExportFormat): string {
  const ext = format === 'json' ? 'json' : 'md'
  return `${slugify(projectName)}-report-${slugify(report.type)}-demo.${ext}`
}

export function buildReportJson(
  project: Pick<Project, 'id' | 'name' | 'client'>,
  report: ReportMeta,
  doc: ReportDocumentDef,
): string {
  const payload = {
    mock: true,
    notice: DEMO_NOTICE,
    generatedAt: new Date().toISOString(),
    supportedExports: SUPPORTED_EXPORT_FORMATS,
    project: { id: project.id, name: project.name, client: project.client },
    report: {
      id: report.id,
      title: report.title,
      type: report.type,
      status: report.status,
      framework: report.framework,
      author: report.author,
      modified: report.modified,
      pages: report.pages,
      words: report.words,
    },
    document: {
      classification: doc.classification,
      sections: doc.sections.map(section => ({
        num: section.def.num,
        title: section.def.title,
        blocks: section.blocks,
      })),
    },
  }
  return JSON.stringify(payload, null, 2)
}

function blockToMarkdown(block: SectionBlock): string {
  switch (block.kind) {
    case 'paragraph':
      return block.text
    case 'note': {
      const title = block.title ? `**${block.title}:** ` : ''
      return `> ${title}${block.text}`
    }
    case 'riskScore':
      return `> Overall risk score: **${block.level}** (CVSS max: ${block.cvss})`
    case 'table': {
      const header = `| ${block.columns.join(' | ')} |`
      const divider = `| ${block.columns.map(() => '---').join(' | ')} |`
      const rows = block.rows.map(row => `| ${row.join(' | ')} |`)
      return [header, divider, ...rows].join('\n')
    }
    case 'phases':
      return block.items
        .map(item => `**${item.title}** (${item.state.toUpperCase()})\n\n${item.text}`)
        .join('\n\n')
    case 'code':
      return `\`\`\`\n${block.code}\n\`\`\``
    case 'steps':
      return block.items
        .map((item, i) => `${i + 1}. ${item.action} (effort: ${item.effort}, risk impact: ${item.impact})`)
        .join('\n')
  }
}

export function buildReportMarkdown(
  project: Pick<Project, 'id' | 'name' | 'client'>,
  report: ReportMeta,
  doc: ReportDocumentDef,
): string {
  const lines: string[] = [
    '<!--',
    '  DEMO EXPORT - Raptix web console (web-raptix demo build)',
    '  Generated from sample fixture data, not from a live engagement.',
    '  Do not use as a real assessment deliverable.',
    '-->',
    '',
    `# ${report.title}`,
    '',
    `- **Project:** ${project.name} (${project.client})`,
    `- **Report type:** ${report.type}`,
    `- **Status:** ${report.status}`,
    `- **Framework:** ${report.framework}`,
    `- **Author:** ${report.author}`,
    `- **Last modified:** ${report.modified}`,
    `- **Classification:** ${doc.classification}`,
    '',
    `> [DEMO DATA] ${DEMO_NOTICE}`,
    '',
  ]
  for (const section of doc.sections) {
    lines.push(`## ${section.def.num}. ${section.def.title}`, '')
    for (const block of section.blocks) {
      lines.push(blockToMarkdown(block), '')
    }
  }
  lines.push('---', '', `*Demo export generated by the Raptix web console (mock data) on ${new Date().toISOString()}.*`)
  return lines.join('\n')
}

export function exportReport(
  project: Pick<Project, 'id' | 'name' | 'client'>,
  report: ReportMeta,
  doc: ReportDocumentDef,
  format: ExportFormat,
): void {
  const filename = buildExportFilename(project.name, report, format)
  const content =
    format === 'json'
      ? buildReportJson(project, report, doc)
      : buildReportMarkdown(project, report, doc)
  const mimeType = format === 'json' ? 'application/json' : 'text/markdown'
  const blob = new Blob([content], { type: `${mimeType};charset=utf-8` })
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = filename
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
  window.setTimeout(() => URL.revokeObjectURL(url), 1000)
}
